import pytest
from solution import SQLSanitizer

@pytest.fixture
def san():
    return SQLSanitizer()

def test_basic_string(san):
    assert san.sanitize_string('hello') == 'hello'

def test_escape_quotes(san):
    result = san.sanitize_string("O'Brien")
    assert "'" not in result or result.count("''") >= 1 or result.count("\\'") >= 1

def test_injection_blocked(san):
    assert san.is_safe('1; DROP TABLE users') is False
    assert san.is_safe('1 UNION SELECT * FROM passwords') is False
    assert san.is_safe('admin -- comment') is False

def test_safe_input(san):
    assert san.is_safe('normal text 123') is True
    assert san.is_safe('john.doe@email.com') is True

def test_numeric_valid(san):
    assert san.sanitize_numeric('42') == 42
    assert san.sanitize_numeric('3.14') == 3.14

def test_numeric_invalid(san):
    with pytest.raises((ValueError, TypeError)):
        san.sanitize_numeric('abc')
    with pytest.raises((ValueError, TypeError)):
        san.sanitize_numeric('1; DROP TABLE')
